#!/usr/bin/env node
// Fake Playwright CLI for e2e-rail's own tests (CommonJS on purpose: this package.json has no "type").
//   node cli.js test --list …        -> prints <cwd>/stub/list.json
//   node cli.js test …               -> writes <cwd>/stub/report-*.json to the JSON output path, exits STUB_PW_RC
//   node cli.js merge-reports … <d>  -> writes <d>/index.html
// Every stub JSON may contain <ABS_APP_DIR>; it is replaced by process.cwd() (the app dir).
const fs = require('node:fs');
const path = require('node:path');
const stub = path.join(process.cwd(), 'stub');
const argv = process.argv.slice(2);
const read = (file) => fs.readFileSync(file, 'utf8').replace(/<ABS_APP_DIR>/g, process.cwd());
if (process.env.STUB_PW_ARGV_FILE) fs.writeFileSync(process.env.STUB_PW_ARGV_FILE, JSON.stringify(argv));
if (argv[0] === 'merge-reports') {
  const dir = argv[argv.length - 1];
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, 'index.html'), '<html>merged</html>');
  process.exit(0);
}
if (argv.includes('--list')) {
  process.stdout.write(read(path.join(stub, 'list.json')));
  process.exit(0);
}
const src = process.env.STUB_PW_REPORT || path.join(stub, 'report-pass.json');
const out = process.env.PLAYWRIGHT_JSON_OUTPUT_FILE || process.env.PLAYWRIGHT_JSON_OUTPUT_NAME;
if (out) {
  fs.mkdirSync(path.dirname(out), { recursive: true });
  fs.writeFileSync(out, read(src));
}
process.exit(Number(process.env.STUB_PW_RC || 0));
